            if not c: continue
            ys=[p[0] for p in c]; xs=[p[1] for p in c]
            sub=[[int(T[i,j]) for j in range(min(xs),max(xs)+1)] for i in range(min(ys),max(ys)+1)]
            col=c[0][0]
            ok = (all(v==col for v in sub[0]) and all(v==col for v in sub[-1]) and
                  all(sub[i][0]==col for i in range(len(sub))) and all(sub[i][-1]==col for i in range(len(sub))))
            inner=[v for r in sub[1:-1] for v in r[1:-1]]
            has_inner = len(inner)>0 and any(v!=col for v in inner)
            if ok and has_inner:
                fill=max(set(inner), key=list(inner).count)
                out.append(((fill)*len(sub[0]) for _ in range(len(sub))))
    return out
